  (* [comment removed for export] *)
  Definition hz_pure (sp ra : word) (D N lo B shi : Z) (LB : list block) (LF : list fframe) : Prop :=
    bv_unsigned sp mod 16 = 0 /\ aceil <= lo /\ lo + AFUZZ_STACK <= bv_unsigned sp /\ bv_unsigned sp <= B /\ B < 2^64 /\ bv_unsigned sp <= 0x7fffffffffff
    /\ bv_unsigned ra mod 2 = 0 /\ 0 <= N < 2^26 /\ D mod 16 = 0 /\ 0 <= D /\ D + N <= 2^64 /\ bv_unsigned sp + 64 <= shi
    /\ (1 <= N -> exists pD, In (pD, D, N) LB) /\ (N = 0 -> D = AFUZZ_EMPTY)
    /\ (length LF + AFUZZ_FRAMES <= AFS_MAXLIVE)%nat
    /\ lb_bytes LB + AFUZZ_LIVE <= as_LIVE_MAX H /\ Z.of_nat (length LB) + AFUZZ_CNT <= as_LIVE_CNT_MAX H.

  (* [comment removed for export] *)
  Definition hz_LB1 (p1 : bptr) (allocb : Z) (p2 : bptr) (regb : Z) (p3 : bptr) (cfgb : Z) (p4 : bptr) (schedb : Z) (LB : list block) : list block :=
    (p4, schedb, NEWSZ_SCH) :: (p3, cfgb, NEWSZ_CFG) :: (p2, regb, NEWSZ_REG) :: (p1, allocb, SZ_ALLOCIMPL) :: LB.

  Definition hz_cost1 : Z := as_Cm H 16 + alloc_obj_registry_cost H + make_svc_config_cost H + make_svc_sched_cost H.

  (* [comment removed for export] *)
  Definition hz_LBR (p1 : bptr) (allocb : Z) (p2 : bptr) (regb : Z) (LB : list block) : list block :=
    (p2, regb, NEWSZ_REG) :: (p1, allocb, SZ_ALLOCIMPL) :: LB.

  (* [comment removed for export] *)
  Definition hzKR (gp tp s8 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (D N lo B shi : Z) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 s9 s10 : word) (HS : mem -> Prop)
      (m0 : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m (errv : word) (s' : as_St H) (spa ff fp : Z) (gap : list cell)
                    (p1 : bptr) (allocb : Z) (p2 : bptr) (regb : Z)
                    (j8 j24 j4 j16 j40 j16b j40b j344 j480 : list byte) (XS : list (Z * Z)),
      as_VIS H s' (cfg_ms c) = MS (mkR (Z_to_bv 64 P_HZ_RET_REG) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                                       (Z_to_bv 64 regb) a1 a2 a3 a4 a5 a6 a7
                                       (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 (ff + 64))
                                       (Z_to_bv 64 N) (Z_to_bv 64 D) s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
                                  F (ret_pc (Z_to_bv 64 P_HZ_RET_REG)) fc None m (seg_rom asegs)
      /\ (spa = bv_unsigned sp + -192 \/ spa = bv_unsigned sp + -208) /\ fresh_frame H LF 4 ff fp
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m /\ stk asegs m lo spa
      /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B /\ as_RHEAP H s LB m0
      /\ as_RHEAP H s' (hz_LBR p1 allocb p2 regb LB) m /\ rblock_range regb NEWSZ_REG
      /\ ARegistry (hz_LBR p1 allocb p2 regb LB) m regb (ff + 128) 0 0
      /\ AAllocImpl (hz_LBR p1 allocb p2 regb LB) m allocb
      /\ AXImg m /\ ACanaryReads m /\ acanary m /\ HS m
      /\ rw_cells asegs m spa [CB 8 j8; C8 (Z_to_bv 64 ff); C8 (Z_to_bv 64 allocb); CB 24 j24; CB 40 (poison_bytes 40 0); C8 (Z_to_bv 64 18446744073709551615)]
      /\ rw_cells asegs m (spa + 96) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 96)
      /\ rw_cells asegs m (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
      /\ rw_cells asegs m ff (hz_hdr spa ++ hz_frm [C8 (Z_to_bv 64 AVP_CFGMAKER); C4 (wz 4294967295); CB 4 j4] j16 [CB 24 (poison_bytes 24 0)] j40
                                               [C8 (Z_to_bv 64 allocb); CB 16 j16b] j40b [CB 344 j344] j480
                              ++ [C8 (Z_to_bv 64 fp)])
      /\ rw_cells asegs m (Z.shiftr ff 3 + 2147450880) hz_sh1 /\ rw_cells asegs m fp [C1 (b8 1)]
      /\ as_RFS H ((4, ff, fp) :: LF) m /\ ACONST m /\ stack0 m lo shi
      /\ Forall (fs_scratch H ((4, ff, fp) :: LF)) XS
      /\ xpres H LB (bv_unsigned sp) ((fr4_XS H ff fp ++ [(AERRNO, AERRNO + 4)]%Z) ++ XS) m0 m
      /\ as_AL H s' >= as_AL H s - (as_Cm H 16 + alloc_obj_registry_cost H).

  (* [comment removed for export] *)
  Definition hzK1 (gp tp s8 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (D N lo B shi : Z) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 s9 s10 : word) (HS : mem -> Prop)
      (m0 : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m (s' : as_St H) (spa ff fp : Z) (gap : list cell)
                    (p1 : bptr) (allocb : Z) (p2 : bptr) (regb : Z) (p3 : bptr) (cfgb : Z) (p4 : bptr) (schedb : Z)
                    (j8 j7 j24 j4 j16 j40 j40b j344 j480 : list byte) (XS : list (Z * Z)),
      as_VIS H s' (cfg_ms c) = MS (mkR (Z_to_bv 64 P_HZ_RET_SCT) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                                       (Z_to_bv 64 (spa + 16)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 D) (Z_to_bv 64 N) a4 a5 a6 a7
                                       (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 (ff + 64))
                                       (Z_to_bv 64 N) (Z_to_bv 64 D) s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
                                  F (Z_to_bv 64 P_A_STREAM_CTOR) fc None m (seg_rom asegs)
      /\ (spa = bv_unsigned sp + -192 \/ spa = bv_unsigned sp + -208) /\ fresh_frame H LF 4 ff fp
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m /\ stk asegs m lo spa
      /\ rw_cells asegs m (errno_addr tp) [C4 (wz 0)] /\ as_rauxv_ok H m B /\ as_RHEAP H s LB m0
      /\ as_RHEAP H s' (hz_LB1 p1 allocb p2 regb p3 cfgb p4 schedb LB) m
      /\ AScheduler (hz_LB1 p1 allocb p2 regb p3 cfgb p4 schedb LB) m schedb (mkSCH (sched_hdr (ff + 128) cfgb) 0 0 0)
      /\ ARegistry (hz_LB1 p1 allocb p2 regb p3 cfgb p4 schedb LB) m regb (ff + 128) schedb 0
      /\ AConfigSvc (hz_LB1 p1 allocb p2 regb p3 cfgb p4 schedb LB) m cfgb (cfg_hdr (ff + 128))
      /\ AAllocImpl (hz_LB1 p1 allocb p2 regb p3 cfgb p4 schedb LB) m allocb
      /\ AXImg m /\ ACanaryReads m /\ acanary m /\ HS m
      /\ rw_cells asegs m spa [CB 8 j8; C8 (Z_to_bv 64 ff); CB 1 [b8 0]; CB 7 j7; CB 24 j24; CB 40 (poison_bytes 40 0); C8 (Z_to_bv 64 18446744073709551615)]
      /\ rw_cells asegs m (spa + 96) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 96)
      /\ rw_cells asegs m (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
      /\ rw_cells asegs m ff (hz_hdr spa ++ hz_frm [C8 (Z_to_bv 64 AVP_CFGMAKER); C4 (wz 4294967295); CB 4 j4] j16 [CB 24 (poison_bytes 24 0)] j40
                                               [C8 (Z_to_bv 64 allocb); C8 (Z_to_bv 64 regb); C8 (Z_to_bv 64 schedb)] j40b [CB 344 j344] j480
                              ++ [C8 (Z_to_bv 64 fp)])
      /\ rw_cells asegs m (Z.shiftr ff 3 + 2147450880) hz_sh2 /\ rw_cells asegs m fp [C1 (b8 1)]
      /\ as_RFS H ((4, ff, fp) :: LF) m /\ ACONST m /\ stack0 m lo shi
      /\ Forall (fs_scratch H ((4, ff, fp) :: LF)) XS
      /\ xpres H LB (bv_unsigned sp) ((fr4_XS H ff fp ++ [(AERRNO, AERRNO + 4)]%Z) ++ XS) m0 m
      /\ as_AL H s' >= as_AL H s - hz_cost1.


